public final class ExpeditionAudit {
 private static int checks;
 private static void check(boolean b,String m){checks++;if(!b)throw new AssertionError(m);}
 public static void main(String[] args)throws Exception{PersonaRegistry.bootstrap();party();map();store();combat();clock();previews();System.out.println("PASS expedition: "+checks+" checks; invitations, transfers, shared-map persistence/reset, shop gates, damage items/affinities, escape success/failure, Dark Hour+ and creative assets. Offline only.");}
 private static void party(){
  var p=new PartyRoster();p.create("alice");check(p.group("alice")!=null,"leader creates party");p.invite("alice","bob",100);check(p.group("bob")==null,"invitation requires consent");p.accept("bob",150);check(p.same("alice","bob"),"accepted membership");p.accept("bob",160);check(p.group("alice").members().size()==2,"replayed invite cannot duplicate member");p.invite("bob","eve",200);check(p.invitation("eve",220)==null,"only leader invites");p.invite("alice","eve",200);p.accept("eve",120201);check(p.group("eve")==null,"expired invitation");p.invite("alice","eve",300);p.decline("eve");p.accept("eve",350);check(p.group("eve")==null,"declined invitation");
  var json=new com.google.gson.Gson();var saved=json.fromJson(json.toJson(p),PartyRoster.class);saved.sanitize();check(saved.same("alice","bob"),"membership survives restart");saved.leave("alice");check(saved.group("bob").members().get(0).equals("bob"),"leadership succession");saved.leave("bob");check(saved.groups.isEmpty(),"empty party removed");
  var from=new PlayerPersonaData();var to=new PlayerPersonaData();from.addYen(1000);check(PartyTransfers.yen(from,to,250)&&from.yen()==750&&to.yen()==250,"yen conservation");check(!PartyTransfers.yen(from,to,-1)&&!PartyTransfers.yen(from,to,751)&&from.yen()==750&&to.yen()==250,"negative/overdraft rejected atomically");to.addYen(Long.MAX_VALUE);check(!PartyTransfers.yen(from,to,1)&&from.yen()==750,"overflow has no debit");
  var a=EquipmentLoadout.starter();var b=EquipmentLoadout.starter();a.addSupply("medicine");a.addSupply("medicine");check(PartyTransfers.supply(a,b,"medicine",2)&&a.count("medicine")==0&&b.count("medicine")==2,"supply quantity conserved");check(!PartyTransfers.supply(a,b,"medicine",1),"same item cannot be sent twice");a.addSupply("medicine");b.supplies.put("medicine",999);check(!PartyTransfers.supply(a,b,"medicine",1)&&a.count("medicine")==1,"full recipient does not consume source");a.grant("gladius");a.equip("gladius");check(!PartyTransfers.gear(a,b,"gladius"),"equipped item protected");a.remove(EquipmentCatalog.Slot.WEAPON);check(PartyTransfers.gear(a,b,"gladius")&&!a.owned.contains("gladius")&&b.owned.contains("gladius"),"unequipped ownership transferred");check(!PartyTransfers.gear(a,b,"gladius"),"no duplicate equipment");
 }
 private static void map(){
  var a=new TartarusMapData();var b=new TartarusMapData();a.reset(7);b.reset(7);a.reveal(1,-36,-36);b.reveal(2,12,24);b.seeChest(2,1);check(a.merge(b)&&a.known(2,12,24)&&a.chest(2,1),"share other floor and chest");b.merge(a);check(b.known(1,-36,-36),"bidirectional union");var restored=TartarusMapData.load(a.save());check(restored.known(2,12,24)&&restored.chest(2,1),"shared chart persists");a.reset(8);check(!a.merge(b)&&!a.known(2,12,24),"old exploration cannot leak across reset");
  var population=new TartarusPopulation();var values=new HashSet<Integer>();for(int f=1;f<250;f++)if(!TartarusInteriorLayout.fixedFloor(f)){int n=population.count(987,f);check(n>=5&&n<=10,"new 5-10 range");values.add(n);}check(values.size()==6,"all population counts reachable");var legacy=new CompoundTag();legacy.m_128405_("min",10);legacy.m_128405_("max",20);var counts=new CompoundTag();counts.m_128405_("1",14);legacy.m_128365_("counts",counts);var migrated=TartarusPopulation.load(legacy);check(migrated.minimum==5&&migrated.maximum==10&&migrated.count(0,1)==10,"legacy default migration");legacy.m_128405_("min",3);legacy.m_128405_("max",8);check(TartarusPopulation.load(legacy).maximum==8,"preserve customized population");
 }
 private static void store()throws Exception{
  check(ShopStock.INITIAL.size()==17,"17 initial equipment entries");for(String id:ShopStock.INITIAL)check(EquipmentCatalog.get(id)!=null&&ShopStock.available(id,0),"initial catalog id "+id);
  check(!ShopStock.available("gimlet",0)&&ShopStock.available("gimlet",9)&&!ShopStock.available("lucifer_s_blade",9),"late equipment progression gate");check(!ShopStock.available("invented",9),"unknown item stays unavailable");
  var resource=Path.of("src/main/resources/assets/velvet_eclipse");var language=new com.google.gson.Gson().fromJson(Files.readString(resource.resolve("lang/pt_br.json")),Map.class);
  for(var item:DamageItems.ALL){check(Supplies.get(item.id())!=null,"damage consumable uses existing collection");check(Files.exists(resource.resolve("models/item/"+item.id()+".json"))&&Files.exists(resource.resolve("textures/item/"+item.id()+".png"))&&language.containsKey("item.velvet_eclipse."+item.id()),"creative content complete: "+item.id());}
  check(EquipmentHelp.describe("+Spell Master").contains("metade")&&EquipmentHelp.describe("+Regenerate 3").contains("6%"),"plain descriptions match passives");
 }
 private static BattleCombatant player(){return new BattleCombatant(new UUID(0,1),"Player",BattleSide.PLAYERS,new PersonaInstance("izanagi",30,0,Set.of()),1000,1000,100,100);}
 private static BattleCombatant enemy(String id,int index){var d=EnemyCatalog.get(id);return BattleCombatant.enemy(new UUID(0,index),d.displayName(),d,d.level(),1000,d.sp(),d.skills());}
 private static void combat(){
  var actor=player();var foe=enemy("magic_hand",2);var s=new BattleSession(List.of(actor,foe),new Random(42));int sp=actor.sp();var action=new BattleAction(BattleActionType.ITEM,"agilao_gem",foe.id());var prepared=s.prepare(actor.id(),action);check(prepared!=null&&prepared.hits().get(foe.id()).affinity()==Affinity.WEAK,"offensive item reserves affinity without learned skill");var resolution=s.perform(actor.id(),action);check(foe.hp()==850&&actor.sp()==sp&&resolution.oneMore(),"fixed base damage weakness and 1 More; no SP cost");
  actor=player();var one=enemy("magic_hand",2);var two=enemy("muttering_tiara",3);s=new BattleSession(List.of(actor,one,two));action=new BattleAction(BattleActionType.ITEM,"maragi_gem",one.id());check(s.prepare(actor.id(),action).hits().size()==2,"area item targets entire enemy side");s.perform(actor.id(),action);check(one.hp()==925&&two.hp()==950,"area damage respects each affinity");
  var hand=enemy("wealth_hand",2);var table=enemy("laughing_table",3);check(hand.affinity(Element.PHYSICAL)==Affinity.WEAK&&hand.affinity(Element.PIERCE)==Affinity.NORMAL,"concussion and pierce independent");check(table.affinity(Element.PIERCE)==Affinity.RESIST,"enemy pierce resistance present");
  var custom=new EnemyDefinition("test","Test","maya",1,2,2,1000,20,new PersonaStats(1,1,1,1,1),Map.of(Element.PIERCE,Affinity.WEAK),Set.of(),Element.SLASH,1,false);var pierce=BattleCombatant.enemy(new UUID(0,7),"Target",custom,2,1000,20,Set.of());actor=player();var gear=EquipmentCatalog.get("short_bow");actor.equipment(new EquipmentBonuses(List.of(gear)));s=new BattleSession(List.of(actor,pierce));action=BattleAction.attack(pierce.id());prepared=s.prepare(actor.id(),action);check(prepared.hit().element()==Element.PIERCE&&prepared.hit().affinity()==Affinity.WEAK,"bow basic attack resolves pierce weakness");
  int failures=0,successes=0;var rng=new Random(19284);for(int i=0;i<200;i++){actor=player();foe=enemy("magic_hand",2);s=new BattleSession(List.of(actor,foe),rng);check(s.escapeChance()>=.2&&s.escapeChance()<=.6,"escape cannot be guaranteed");if(s.attemptEscape(actor.id()))successes++;else{failures++;check(s.currentActor().side()==BattleSide.ENEMIES,"failed escape consumes turn");}}check(failures>50&&successes>20,"both escape outcomes occur repeatedly");
 }
 private static void clock(){
  var timer=new DarkHourTimer();check(!timer.extend(300000),"cannot extend inactive hour");timer.advance(18000,0);check(timer.extend(300000)&&timer.remaining==2100000&&timer.skyTime()>=18000,"extension stays within Dark Hour sky phase");timer=DarkHourTimer.load(timer.save());check(timer.remaining==2100000,"extension persists beyond initial duration");timer.advance(timer.skyTime()+1,2099999);check(timer.remaining==1&&timer.running,"does not end before extended deadline");check(timer.advance(timer.skyTime()+1,1),"extended expiry ends hour");
  var rng=new Random(5021);int extra=0;for(int i=0;i<1000;i++){var r=ShuffleRules.roll(10,Set.of(),rng,false);check(r.cards().size()<=5,"at most five shuffle cards");if(r.cards().stream().anyMatch(c->c.kind()==ShuffleRules.Kind.DARK_HOUR))extra++;}check(extra>=25&&extra<=80,"normal Dark Hour+ probability around 5%");for(int i=0;i<30;i++){var r=ShuffleRules.roll(10,Set.of(),rng,true);check(r.cards().stream().filter(c->c.kind()==ShuffleRules.Kind.DARK_HOUR).count()==1&&r.cards().size()<=5,"red Shadow guaranteed unique time card");}
  var d=new ShuffleData();var round=ShuffleRules.roll(25,Set.of(),rng,true);d.add(round);int at=0;while(round.cards().get(at).kind()!=ShuffleRules.Kind.DARK_HOUR)at++;check(ShuffleRewards.claim(d,new PlayerPersonaData(),round.token(),at,id->true).card()!=null,"time card consumed once");check(ShuffleRewards.claim(d,new PlayerPersonaData(),round.token(),at,id->true).card()==null,"replayed time card cannot extend again");
 }
 private static void previews()throws Exception{
  var image=new java.awt.image.BufferedImage(1000,460,java.awt.image.BufferedImage.TYPE_INT_ARGB);var g=image.createGraphics();g.setColor(new java.awt.Color(0x06142B));g.fillRect(0,0,1000,460);var font=java.awt.Font.createFont(java.awt.Font.TRUETYPE_FONT,Path.of("src/main/resources/assets/velvet_eclipse/font/body.ttf").toFile());var c=new Canvas(g,font);
  var map=new TartarusMapNetwork.View(0,0,0,10,10,new byte[13],List.of());com.gx.velveteclipse.client.tartarus.TartarusMapDesign.paint(c,map,65,90,100,5,5,90,false);com.gx.velveteclipse.client.tartarus.TartarusMapDesign.paint(c,map,250,90,200,5,5,90,true);
  var choice=new ShuffleSnapshot.Choice(ShuffleRules.Kind.DARK_HOUR,"",300000,1,"DARK HOUR+","+5 minutos",null);com.gx.velveteclipse.client.shuffle.ShuffleDesign.card(c,choice,new com.gx.velveteclipse.client.menu.MenuDesign.Rect(600,55,138,211),true,1);c.text("DARK HOUR+",575,307,26,0xFFDDFFFF,0);c.text("MINIMAPA / HALL",45,27,24,0xFFDDFFFF,0);g.dispose();Files.createDirectories(Path.of("build/reports/expedition"));javax.imageio.ImageIO.write(image,"png",Path.of("build/reports/expedition/hall-card.png").toFile());
 }
 private record Canvas(java.awt.Graphics2D g,java.awt.Font font) implements com.gx.velveteclipse.client.menu.MenuDesign.Canvas {
  public void fill(double x,double y,double w,double h,int c){g.setColor(new java.awt.Color(c,true));g.fill(new java.awt.geom.Rectangle2D.Double(x,y,w,h));}
  public void poly(double[] a,int c){var p=new java.awt.geom.Path2D.Double();p.moveTo(a[0],a[1]);for(int i=2;i<a.length;i+=2)p.lineTo(a[i],a[i+1]);p.closePath();g.setColor(new java.awt.Color(c,true));g.fill(p);}
  public void text(String s,double x,double y,double size,int c,double angle){var old=g.getTransform();g.translate(x,y);g.rotate(Math.toRadians(angle));g.setColor(new java.awt.Color(c,true));g.setFont(font.deriveFont((float)size));g.drawString(s,0,(int)(size*.8));g.setTransform(old);}
  public double width(String s,double size){return g.getFontMetrics(font.deriveFont((float)size)).stringWidth(s);}public void item(int slot,double x,double y){}
 }
}
